INSERT INTO `categories` (`id`, `cate_name`, `cate_des`, `cate_url`, `created_at`, `updated_at`, `teacher_id`) VALUES
(17, 'American Diploma', 'The American Diploma in Mathematics encompasses a wide range of topics, including algebra, statistics, calculus, geometry, and trigonometry. This diploma course is designed to enhance and refresh mathematical knowledge, covering essential mathematical concepts and their applications in various professional fields. It aims to widen career options as mathematics is fundamental in a world that is constantly advancing with new technologies.', '4162024X07X19X18X17X36EducationXsystemXinXusaX1X320.webp', '2024-05-04 06:12:58', '2024-07-23 11:38:00', 68),
(19, 'IGCSE \" International General Certificate of Secondary Education\"', 'The International General Certificate of Secondary Education (IGCSE) is an English language based secondary qualification similar to the GCSE and is recognised in the United Kingdom as being equivalent to the GCSE for the purposes of recognising prior attainment. It was developed by Cambridge Assessment International Education.', '5472024X07X19X18X28X53640pxXIGCSE_cover.jpg', '2024-07-19 15:28:53', '2024-07-19 15:28:53', 252),
(20, 'Egyptian National Education', 'Egypt\'s education system is structured around a 6-3-3 model, comprising six years of primary school, three years of preparatory school, and three years of secondary school. Education is compulsory for nine years, from ages 6 to 14, encompassing the primary and preparatory stages.', '4692024X12X26X16X02X53UntitledXdesignX2X1.png', '2024-12-26 14:02:53', '2025-07-01 16:57:51', 333),
(22, 'Saudi Arabia\'s Education System', 'The education system in Saudi Arabia is structured around three main levels: primary, intermediate, and secondary, with free and compulsory education for citizens and residents. It encompasses public (government-funded)', '2882025X07X01X20X04X00MOE_of_KSA.png', '2025-07-01 17:04:00', '2025-07-01 17:04:00', 252);
