INSERT INTO `courses` (`id`, `course_name`, `category_id`, `course_des`, `course_url`, `pre_requisition`, `gain`, `created_at`, `updated_at`, `teacher_id`, `user_id`, `type`, `currancy_id`) VALUES
(15, 'EST 1', 17, 'The Egyptian Scholastic Test (EST) includes two main sections for math: Math without Calculator and Math with Calculator. These sections are designed to assess students\' mathematical skills and knowledge, and they are part of the EST I exam, which is a standardized admission test for students in the American Educational system in Egypt. The EST I also includes sections for Literacy 1, Literacy 2, and an optional essay section to measure students\' language writing skills.', '2024X06X06X09X17X011602estX.jpeg', NULL, NULL, '2024-04-29 07:09:08', '2025-01-11 10:55:02', 78, NULL, 'Course', 3),
(16, 'EST 2', 17, 'The EST II, on the other hand, is a subject-based test that covers various subjects, including Math, Biology, Physics and Chemistry. The Math section of the EST II measures basic scientific knowledge, scientific reasoning, and higher-order thinking skills, particularly for students pursuing education in specific majors related to engineering, science, and healthcare.', '2024X06X06X09X16X445506estX.jpeg', NULL, NULL, '2024-04-29 07:11:22', '2024-10-30 13:58:54', 78, NULL, 'Course', 3),
(17, 'SAT', 17, 'The SAT, or Scholastic Assessment Test, is a standardized test administered by the College Board, a non-profit organization that also runs other programs such as the PSAT and AP exams. It is widely used by colleges and universities in the United States as an entrance exam for making admissions decisions.', '2024X06X06X09X07X341708sat.png', NULL, NULL, '2024-04-29 07:14:15', '2024-10-30 13:51:58', 78, NULL, 'Course', 3),
(18, 'ACT', 17, 'The ACT (American College Testing) is an entrance exam used by most colleges and universities to make admissions decisions. It is a multiple-choice, pencil-and-paper test administered by ACT, Inc. The purpose of the ACT test is to measure a high school student\'s readiness for college and provide colleges with one common data point that can be used to compare all applicants.', '2024X06X06X09X07X185508act.jpeg', NULL, NULL, '2024-04-29 07:14:57', '2024-10-30 13:49:00', 78, NULL, 'Course', 3),
(19, 'AP Calculus', 17, 'The AP Calculus AB Exam is designed to assess students\' understanding of the mathematical concepts covered in the course units, as well as their ability to determine the proper formulas and procedures to solve problems and communicate their work with the correct notations. The exam questions assess the course concepts and skills outlined in the course framework, and it has consistent question types, weighting, and scoring guidelines every year.', '2024X06X06X09X07X481103ap.png', NULL, NULL, '2024-04-29 07:18:10', '2024-10-30 13:32:57', 78, NULL, 'Course', 3),
